#version 300 es
layout(location=0) in vec2 position;
void main() { gl_Position = vec4(position, 0.0, 1.0); }

#version 300 es
precision highp float;
out vec4 fragColor;
struct GrapeStruct0 { float[2][3] f0; float f1; };
void main() {
  float n_1_p0 = 0.25;
  float n_2_p2 = (n_1_p0 * 2.0);
  GrapeStruct0 n_4_p2 = GrapeStruct0(float[2][3](float[2](0.0, 0.0), float[2](0.0, 0.0), float[2](0.0, 0.0)), 0.0);
  float n_5_p1 = (n_4_p2).f1;
  vec4 n_3_p4 = vec4(n_2_p2, n_5_p1, 0.0, 1.0);
  fragColor = n_3_p4;
}
